// 04 - Mutexes: four-core contention, timed_lock, recursive, priority inheritance.
// One suite, one file: it registers itself with the runner; there is no
// list of suites to keep in step with the files.
// GENERATED by micro-os-scaffold (--micro-test-plus).
#include <mtp_board.hpp>
#include "smp_helpers.hpp"

using namespace os::rtos;
using namespace mtp_smp;

namespace
{
  constexpr unsigned mx_increments = 5000;
  mutex* g_mx = nullptr;
  volatile std::uint32_t g_mx_counter = 0;
  volatile unsigned g_mx_wrong_core = 0;

  void*
  count_under_mutex (void* arg)
  {
    const unsigned core = from_arg (arg);
    for (unsigned i = 0; i < mx_increments; ++i)
      {
        (void)g_mx->lock ();
        const std::uint32_t value = g_mx_counter;
        asm volatile ("" ::: "memory");
        g_mx_counter = value + 1;
        (void)g_mx->unlock ();
        if ((i & 0xff) == 0 && mtp_board::cpu_id () != core)
          {
            g_mx_wrong_core = g_mx_wrong_core + 1;
          }
      }
    return nullptr;
  }

  // Step-driven owner on another core: lock `depth` times, then unlock one
  // level each time `g_step` advances.
  volatile unsigned g_step = 0;
  volatile unsigned g_level = 0;
  unsigned g_depth = 1;

  void*
  own_mutex (void*)
  {
    for (unsigned i = 0; i < g_depth; ++i)
      {
        (void)g_mx->lock ();
      }
    store (g_level, g_depth);
    for (unsigned i = 0; i < g_depth; ++i)
      {
        while (load (g_step) <= i)
          {
            sysclock.sleep_for (1);
          }
        (void)g_mx->unlock ();
        store (g_level, g_depth - i - 1);
      }
    return nullptr;
  }

  // Priority inheritance: the low thread on core 1 holds the mutex and
  // spins; the high thread on core 0 blocks on it.
  volatile unsigned g_low_holds = 0;
  volatile unsigned g_low_go = 0;
  volatile thread::priority_t g_low_after = 0;

  void*
  low_holder (void*)
  {
    (void)g_mx->lock ();
    store (g_low_holds, 1u);
    while (load (g_low_go) == 0)
      {
        mtp_board::cpu_relax ();
      }
    (void)g_mx->unlock ();
    g_low_after = this_thread::thread ().priority ();
    return nullptr;
  }

  volatile unsigned g_high_locked = 0;

  void*
  high_waiter (void*)
  {
    (void)g_mx->lock ();
    store (g_high_locked, 1u);
    (void)g_mx->unlock ();
    return nullptr;
  }
} // namespace

mt::static_suite suite_mutex{
  "04 - Mutexes", mtp_board::runner (),
  [] (mt::suite& ts) {
    ts.test ("one mutex, every core, no lost increment", [] (auto& t) {
      mutex mx{ "mtp-count" };
      g_mx = &mx;
      g_mx_counter = 0;
      g_mx_wrong_core = 0;
      thread* threads[ncpu] = {};
      for (unsigned core = 0; core < ncpu; ++core)
        {
          threads[core] = spawn ("mtp-mx", count_under_mutex, as_arg (core),
                                 static_cast<int> (core));
        }
      for (auto* th : threads)
        {
          finish (th);
        }
      t.expect (mt::eq (static_cast<std::uint32_t> (g_mx_counter),
                        static_cast<std::uint32_t> (ncpu * mx_increments)))
          << fmt ("%u increments, none lost", ncpu * mx_increments);
      t.expect (mt::eq (static_cast<unsigned> (g_mx_wrong_core), 0u))
          << "each thread stayed on its core";
    });

    ts.test ("a mutex held on core 1: timed_lock times out, lock waits",
             [] (auto& t) {
               mutex mx{ "mtp-held" };
               g_mx = &mx;
               g_depth = 1;
               store (g_step, 0u);
               store (g_level, 0u);
               thread* th = spawn ("mtp-owner", own_mutex, nullptr, 1);
               const bool owned = wait_until (g_level, ms (100));
               const auto try_result = mx.try_lock ();
               const auto timed = mx.timed_lock (ms (10));
               store (g_step, 1u); // core 1 unlocks a moment later
               const auto locked = mx.lock ();
               if (locked == mtp::ok)
                 {
                   (void)mx.unlock ();
                 }
               finish (th);
               t.expect (owned) << "core 1 owns the mutex";
               t.expect (mt::eq (try_result, mtp::code (EWOULDBLOCK)))
                   << "try_lock () on core 0: EWOULDBLOCK";
               t.expect (mt::eq (timed, mtp::code (ETIMEDOUT)))
                   << "timed_lock (10 ms) on core 0: ETIMEDOUT";
               t.expect (mt::eq (locked, mtp::ok))
                   << "lock () on core 0 returns once core 1 unlocks";
             });

    ts.test ("a recursive mutex is released only at depth 0", [] (auto& t) {
      mutex_recursive mx{ "mtp-recursive" };
      g_mx = &mx;
      g_depth = 2;
      store (g_step, 0u);
      store (g_level, 0u);
      thread* th = spawn ("mtp-owner2", own_mutex, nullptr, 1);
      const bool owned = wait_until (g_level, ms (100));
      const auto at_two = mx.try_lock ();
      store (g_step, 1u);
      while (load (g_level) > 1)
        {
          sysclock.sleep_for (1);
        }
      const auto at_one = mx.try_lock ();
      store (g_step, 2u);
      while (load (g_level) > 0)
        {
          sysclock.sleep_for (1);
        }
      const auto at_zero = mx.try_lock ();
      if (at_zero == mtp::ok)
        {
          (void)mx.unlock ();
        }
      finish (th);
      t.expect (owned) << "core 1 locked it twice";
      t.expect (mt::eq (at_two, mtp::code (EWOULDBLOCK))) << "refused at depth 2";
      t.expect (mt::eq (at_one, mtp::code (EWOULDBLOCK))) << "refused at depth 1";
      t.expect (mt::eq (at_zero, mtp::ok)) << "taken at depth 0";
    });

    ts.test ("priority inheritance across cores", [] (auto& t) {
      mutex::attributes attr;
      attr.mx_protocol = mutex::protocol::inherit;
      mutex mx{ "mtp-inherit", attr };
      g_mx = &mx;
      store (g_low_holds, 0u);
      store (g_low_go, 0u);
      store (g_high_locked, 0u);
      g_low_after = 0;

      thread* low = spawn ("mtp-low", low_holder, nullptr, 1,
                           thread::priority::below_normal);
      const bool holds = wait_until (g_low_holds, ms (100));
      const auto low_before = low->priority ();
      thread* high = spawn ("mtp-high", high_waiter, nullptr, 0,
                            thread::priority::above_normal);
      sysclock.sleep_for (ms (5)); // the high thread blocks on the mutex
      const auto low_boosted = low->priority ();
      const bool high_waiting = load (g_high_locked) == 0;
      store (g_low_go, 1u);
      const bool high_got = wait_until (g_high_locked, ms (100));
      finish (high);
      finish (low);

      t.expect (holds) << "the low thread on core 1 holds the mutex";
      t.expect (mt::eq (static_cast<unsigned> (low_before),
                        static_cast<unsigned> (thread::priority::below_normal)))
          << "at its own priority";
      t.expect (high_waiting) << "the high thread on core 0 waits for it";
      t.expect (mt::eq (static_cast<unsigned> (low_boosted),
                        static_cast<unsigned> (thread::priority::above_normal)))
          << "the holder inherits the waiter's priority";
      t.expect (high_got) << "the waiter gets the mutex when it is released";
      t.expect (mt::eq (static_cast<unsigned> (g_low_after),
                        static_cast<unsigned> (thread::priority::below_normal)))
          << "and the holder drops back to its own priority";
    });
  }
};
